def is_Two_Alter(s: str) -> bool:
    if len(s) == 0:
        return True

    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False

    # Check if no two adjacent characters are the same
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            return False

    # If it passes these checks, it's alternating between two chars
    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0

    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

